/**
 * WISDOM BANK E — buddhism, zen. Compact real entries.
 */

import type { WisdomArchetype } from "./types";

export const WISDOM_BUDDHISM: WisdomArchetype[] = [
  { concept: "The First Noble Truth — Dukkha", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta (SN 56.11)", explanation: "The Buddha's first teaching: this is dukkha — unsatisfactoriness, stress, the subtle unease permeating conditioned existence. Not 'life is suffering' but 'life contains a pervasive unsatisfactoriness, even in pleasant moments, because all conditioned things change.'", application: "Apply the truth as diagnosis, not pessimism: notice the subtle unease beneath pleasant states — the anticipation of their end. The diagnosis is the beginning of the path, not its conclusion.", questions: ["Where is the subtle unease beneath my current pleasant state?", "What is changing right now — and how do I relate to its changing?", "Can I hold dukkha as diagnosis rather than worldview?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 56", "The Middle Length Discourses"], excerpt: "This is the noble truth of dukkha: birth is dukkha, aging is dukkha, death is dukkha.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "four_noble_truths", "dukkha", "first_truth", "diagnosis", "unsatisfactoriness"], difficulty: "beginner", minutes: 6 },
  { concept: "The Second Noble Truth — Craving (Tanha)", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta (SN 56.11)", explanation: "The cause of dukkha: tanha — craving, thirst — in three forms: craving for pleasure, craving for becoming, craving for non-becoming. The teaching's precision: suffering is not caused by the world but by the thirst that grasps it.", application: "Use the three cravings as a daily diagnostic: which thirst is active — for pleasure, for becoming (more), or for non-becoming (escape)? The naming is the beginning of the cessation.", questions: ["Which of the three cravings is active in me right now?", "What is the thirst beneath my current grasping?", "Can I name the craving without obeying it?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 56", "The Linked Discourses"], excerpt: "This is the noble truth of the origin of dukkha: the craving that leads to renewed existence.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "second_truth", "tanha", "craving", "thirst", "cause", "diagnosis"], difficulty: "beginner", minutes: 6 },
  { concept: "The Third Noble Truth — Cessation (Nirodha)", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta (SN 56.11)", explanation: "The cessation of dukkha is possible: the complete fading away of craving, its abandonment, its relinquishment. The teaching's optimism is not wishful but structural — the cause being removable, the effect is removable. Nibbana is not a distant heaven but the cessation's present possibility.", application: "Hold the third truth as the library's horizon: cessation is possible, not as a belief but as a structural consequence of removing the cause. The application is the cause's removal — one craving at a time.", questions: ["What is the structural relationship between cause and effect in my suffering?", "Where is cessation conceivable — even if not yet realized?", "What is one craving whose removal is available today?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 56", "Udana 8.1-8.3"], excerpt: "This is the noble truth of the cessation of dukkha: the fading away of craving.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "third_truth", "nirodha", "cessation", "nibbana", "relinquishment", "possibility"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Fourth Noble Truth — The Path (Magga)", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta (SN 56.11)", explanation: "The path to cessation: the noble eightfold path — right view, intention, speech, action, livelihood, effort, mindfulness, concentration. The fourth truth is the prescription: not a belief but a practice, eight factors trained together.", application: "Use the eight factors as the library's completeness audit: which factor is strongest, which weakest? The path is simultaneous — all eight trained together, each supporting the others.", questions: ["Which of the eight factors is strongest in my life?", "Which is weakest — and what is its cost?", "What is one act of right speech, effort, or mindfulness available today?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 45.8", "The Middle Length Discourses"], excerpt: "This is the noble truth of the path: the eightfold path.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "fourth_truth", "magga", "eightfold_path", "prescription", "practice"], difficulty: "beginner", minutes: 7 },
  { concept: "Anicca — Impermanence", tradition: "Buddhism", source: "Dhammapada 1.1-1.5; SN 22.45", explanation: "The first characteristic of all conditioned things: anicca — impermanence. Everything arisen passes away. The teaching is not morbid but liberating: what changes can be released. The Buddha's instruction: contemplate impermanence until it is not a belief but a perception.", application: "Practice anicca as perception, not philosophy: watch one thing change right now — the breath, a sound, a thought. The perception, repeated, becomes the release mechanism.", questions: ["What is changing right now, as I read this?", "Where am I gripping what is impermanent?", "Can impermanence be perceived — not merely believed?"], references: ["Dhammapada 1.1-1.5", "Samyutta Nikaya 22.45", "Anicca Sutta"], excerpt: "All conditioned things are impermanent. Contemplate until it is perception, not belief.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["buddhism", "anicca", "impermanence", "characteristic", "perception", "release"], difficulty: "beginner", minutes: 5 },
  { concept: "Dukkha — The Three Marks' Second", tradition: "Buddhism", source: "Dhammapada; SN 22.45", explanation: "The second characteristic: dukkha — unsatisfactoriness. What is impermanent, when clung to, is dukkha. The teaching's precision: dukkha is not 'everything is pain' but 'clinging to the impermanent is pain'. The clinging is the variable; the impermanence is the constant.", application: "Apply the formula: impermanence + clinging = dukkha. The application is the clinging's reduction — not the world's change. The variable is the grip, not the grippee.", questions: ["Where is my clinging to the impermanent?", "What is the grip's current object — and its cost?", "Can I distinguish the impermanence (constant) from the clinging (variable)?"], references: ["Dhammapada 1.1-1.5", "Samyutta Nikaya 22.45", "The Middle Length Discourses"], excerpt: "What is impermanent, when clung to, is dukkha. The clinging is the variable.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["buddhism", "dukkha", "unsatisfactoriness", "clinging", "three_marks", "variable"], difficulty: "beginner", minutes: 6 },
  { concept: "Anatta — Non-Self", tradition: "Buddhism", source: "Anatta-lakkhana Sutta (SN 22.59)", explanation: "The third characteristic: anatta — non-self. Form, feeling, perception, formations, consciousness — none is the self. The teaching's method: each aggregate is impermanent; what is impermanent is suffering; what is suffering is not self. The self is not denied; it is not found.", application: "Practice anatta as subtraction: when a state claims identity ('I am angry'), locate the aggregate (feeling, formation) and subtract. The subtraction is not denial — the anger is real as aggregate, unreal as self.", questions: ["Which aggregate is claiming identity right now?", "What is impermanent about it — and what is the suffering in mistaking it for self?", "What remains after the subtraction?"], references: ["Anatta-lakkhana Sutta (SN 22.59)", "Samyutta Nikaya 22", "The Middle Length Discourses"], excerpt: "Form is not self, feeling is not self, perception is not self, formations are not self, consciousness is not self.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "anatta", "non_self", "aggregates", "subtraction", "three_marks"], difficulty: "advanced", minutes: 9 },
  { concept: "The Five Aggregates — Khandhas", tradition: "Buddhism", source: "SN 22.48; Anatta-lakkhana Sutta", explanation: "The Buddha's anatomy of the person: five aggregates — form (rupa), feeling (vedana), perception (sanna), mental formations (sankhara), consciousness (vinnana). The person is the aggregates' process, not a thing behind them. The teaching's precision: the aggregates are real; the 'one behind them' is not found.", application: "Use the five aggregates as the library's daily map: in any experience, locate the aggregate speaking. The map's purpose is not fragmentation but accuracy — the process is seen as process.", questions: ["Which aggregate is speaking in my current state?", "Where am I positing a 'one behind them'?", "What is the difference between the process and the posited one?"], references: ["Samyutta Nikaya 22.48", "Anatta-lakkhana Sutta (SN 22.59)", "The Middle Length Discourses"], excerpt: "Form, feeling, perception, formations, consciousness — the five aggregates.", evidence: "traditional", dimensions: ["thought", "body"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "five_aggregates", "khandhas", "form", "feeling", "perception", "formations", "consciousness"], difficulty: "intermediate", minutes: 8 },
  { concept: "Dependent Origination — Pratityasamutpada", tradition: "Buddhism", source: "SN 12.1-12.2; Dhammacakkappavattana Sutta", explanation: "The Buddha's central law: dependent origination — this being, that becomes; this not being, that does not become. The twelve links (ignorance to aging-and-death) are the law's detailed application. The teaching's precision: nothing arises independently; everything arises in dependence.", application: "Use dependent origination as the library's systems view: any state can be traced to its conditions. The application is the condition's change — not the state's force. Find the link; change the condition.", questions: ["What are the conditions of my current state?", "Which link in the chain is workable?", "What is the difference between changing the state and changing its conditions?"], references: ["Samyutta Nikaya 12.1-12.2", "Dhammacakkappavattana Sutta", "The Middle Length Discourses"], excerpt: "This being, that becomes. This not being, that does not become.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "dependent_origination", "pratityasamutpada", "twelve_links", "conditions", "systems"], difficulty: "advanced", minutes: 9 },
  { concept: "The Twelve Links — From Ignorance to Aging-and-Death", tradition: "Buddhism", source: "SN 12.2", explanation: "The twelve links of dependent origination: ignorance, formations, consciousness, name-and-form, the six senses, contact, feeling, craving, clinging, becoming, birth, aging-and-death. The chain's precision: each link conditions the next; the chain's reversal — ignorance's cessation — reverses the whole.", application: "Use the twelve links as the library's deepest diagnostic: locate your current position in the chain. The application is the interruption — at feeling, before craving; at craving, before clinging. The earlier the interruption, the lighter the work.", questions: ["Where am I in the chain right now?", "What is the earliest workable interruption point?", "Can I interrupt at feeling — before craving assembles?"], references: ["Samyutta Nikaya 12.2", "Samyutta Nikaya 12.1-12.10", "The Middle Length Discourses"], excerpt: "Ignorance conditions formations... craving conditions clinging... the whole chain, and its reversal.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "twelve_links", "ignorance", "craving", "clinging", "becoming", "chain", "reversal"], difficulty: "advanced", minutes: 10 },
  { concept: "The Middle Way", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta; SN 56.11", explanation: "The Buddha's first teaching's frame: the middle way between the extremes of indulgence and mortification. The teaching's precision: the extremes are not opposites but the same error in different costumes — both are the self's grasping, one toward pleasure, one toward pain.", application: "Find today's extremes: where is indulgence (overconsumption of input, food, stimulation) and where is mortification (self-punishment, deprivation)? The middle way is not lukewarm compromise but precise calibration.", questions: ["What are today's two extremes?", "Where is my middle — not compromise but precision?", "What would the middle way look like in this specific domain?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 56", "The Middle Length Discourses"], excerpt: "The middle way between indulgence and mortification — the path of precision.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["raja", "karma"], domains: ["growth", "health"], tags: ["buddhism", "middle_way", "extremes", "indulgence", "mortification", "precision"], difficulty: "beginner", minutes: 6 },
  { concept: "The Four Immeasurables — Brahmaviharas", tradition: "Buddhism", source: "Metta Sutta; SN 46.54", explanation: "The four divine abodes: loving-kindness (metta), compassion (karuna), sympathetic joy (mudita), equanimity (upekkha). The teaching's structure: each immeasurable is a response to a specific mental habit — ill will, cruelty, envy, and partiality — and each is trained until immeasurable.", application: "Practice the four as a sequence: metta for the loved one, karuna for the suffering one, mudita for the successful one, upekkha for the difficult one. The sequence is the practice; the immeasurability is the result.", questions: ["Which of the four is strongest in me — and which is absent?", "Who is my difficult one — and can upekkha hold them?", "What is the difference between equanimity and indifference?"], references: ["Metta Sutta (Sn 1.8)", "Samyutta Nikaya 46.54", "The Middle Length Discourses"], excerpt: "Loving-kindness, compassion, sympathetic joy, equanimity — the four immeasurables.", evidence: "traditional", dimensions: ["emotion", "connection", "spirit"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["buddhism", "brahmaviharas", "metta", "karuna", "mudita", "upekkha", "immeasurables"], difficulty: "intermediate", minutes: 8 },
  { concept: "Metta — Loving-Kindness", tradition: "Buddhism", source: "Metta Sutta (Sn 1.8)", explanation: "The Metta Sutta's instruction: as a mother protects her only child, cultivate a boundless heart toward all beings. The teaching's precision: metta is not sentiment but a trained orientation — the wish for welfare, extended without exception.", application: "Practice metta as the library's compassion foundation: begin with yourself, extend to the loved, the neutral, the difficult, all beings. The extension is the practice; the boundlessness is the result.", questions: ["Where is my metta natural — and where is it forced?", "Who is the difficult one — and what is the honest next step?", "Can I distinguish metta (the wish) from its feeling?"], references: ["Metta Sutta (Sn 1.8)", "The Minor Discourses", "Visuddhimagga"], excerpt: "As a mother protects her only child, cultivate a boundless heart toward all beings.", evidence: "traditional", dimensions: ["emotion", "connection", "spirit"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["buddhism", "metta", "loving_kindness", "boundless", "mother", "extension"], difficulty: "beginner", minutes: 6 },
  { concept: "The Noble Silence", tradition: "Buddhism", source: "Theravada tradition; MN 122", explanation: "The Buddha's practice of noble silence: not speaking, and not encouraging others' speaking — the silence of the community, not merely the individual. The teaching's precision: silence is not absence but presence — the space where deep attention becomes possible.", application: "Practice noble silence in one relationship today: a meal, a walk, an evening — speechless by agreement. The application is the discovery that silence is not awkward but spacious.", questions: ["Where is my speech filling space that silence could hold?", "What is one relationship where noble silence could be practiced?", "What is the difference between silence and withdrawal?"], references: ["Maha Satipatthana Sutta (MN 122)", "The Middle Length Discourses", "Theravada monastic tradition"], excerpt: "Noble silence — the community's silence, not merely the individual's.", evidence: "traditional", dimensions: ["thought", "connection", "spirit"], paths: ["raja"], domains: ["relationships", "learning"], tags: ["buddhism", "noble_silence", "community", "speech", "spaciousness", "attention"], difficulty: "beginner", minutes: 5 },
  { concept: "Satipatthana — The Four Foundations of Mindfulness", tradition: "Buddhism", source: "Maha Satipatthana Sutta (MN 10; DN 22)", explanation: "The Buddha's core meditation teaching: the four foundations — body (kaya), feeling (vedana), mind (citta), and mental objects (dhammas). The sutta's promise: one who practices thus, for seven years or even seven days, may realize liberation. The teaching's precision: mindfulness is not one practice but four systematic fields.", application: "Use the four foundations as the library's meditation curriculum: body scan (kaya), feeling-tone (vedana), mind-state (citta), mental-object classification (dhammas). Each foundation is a complete practice; together they are the path's engine.", questions: ["Which foundation is my practice's home — and which is neglected?", "What is the feeling-tone (vedana) of my current state — pleasant, unpleasant, neutral?", "Can I classify the mind's objects without being classified by them?"], references: ["Maha Satipatthana Sutta (MN 10)", "Digha Nikaya 22", "The Middle Length Discourses"], excerpt: "There is one way, monks, for the purification of beings — the four foundations of mindfulness.", evidence: "traditional", dimensions: ["thought", "body", "spirit"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "satipatthana", "four_foundations", "body", "feeling", "mind", "dhammas", "mindfulness"], difficulty: "intermediate", minutes: 9 },
  { concept: "Vedana — The Feeling Tone", tradition: "Buddhism", source: "Vedana Sutta (SN 36.5); Satipatthana", explanation: "The Buddha's precision: every contact produces a feeling-tone — pleasant, unpleasant, or neutral. The teaching's power: vedana is the link between contact and craving. Catch the tone before the craving assembles, and the chain is interrupted at its weakest joint.", application: "Practice vedana as the library's earliest intervention: in any experience, name the tone — pleasant, unpleasant, neutral — before the story. The naming is the interruption; the story is the chain's next link.", questions: ["What is the feeling-tone of my current experience — before the story?", "Where is craving assembling on top of a tone?", "Can I hold the tone without the story — and for how long?"], references: ["Vedana Sutta (SN 36.5)", "Maha Satipatthana Sutta (MN 10)", "Samyutta Nikaya 36"], excerpt: "Every contact produces a feeling-tone: pleasant, unpleasant, or neutral.", evidence: "traditional", dimensions: ["emotion", "thought", "body"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "vedana", "feeling_tone", "pleasant", "unpleasant", "neutral", "early_intervention"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Five Hindrances — Nivarana", tradition: "Buddhism", source: "SN 46.53; Visuddhimagga", explanation: "The five hindrances to concentration: sensual desire (kamacchanda), ill will (vyapada), sloth-torpor (thina-middha), restlessness-worry (uddhacca-kukkucca), and doubt (vicikiccha). The teaching's precision: the hindrances are not moral failings but predictable obstacles — each with its antidote.", application: "Use the five hindrances as the library's practice diagnostic: when sitting fails, name the hindrance. Each has its antidote — sensual desire's is the body's repulsiveness reflection, ill will's is metta, sloth's is attention to light, restlessness's is tranquility, doubt's is the teacher's guidance.", questions: ["Which hindrance is active in my current practice?", "What is its specific antidote?", "Can I name the hindrance without judging it — and apply the antidote?"], references: ["Samyutta Nikaya 46.53", "Visuddhimagga 4", "The Middle Length Discourses"], excerpt: "The five hindrances: sensual desire, ill will, sloth-torpor, restlessness-worry, doubt.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "five_hindrances", "nivarana", "sensual_desire", "ill_will", "sloth", "restlessness", "doubt", "antidotes"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Seven Factors of Awakening — Bojjhangas", tradition: "Buddhism", source: "SN 46.53; Bojjhanga Samyutta", explanation: "The seven factors of awakening: mindfulness (sati), investigation of dhammas (dhammavicaya), energy (viriya), joy (piti), tranquility (passaddhi), concentration (samadhi), and equanimity (upekkha). The teaching's precision: the factors are trained in sequence, and their balance — not their intensity — produces awakening.", application: "Use the seven factors as the library's practice quality audit: which factor is dominant, which deficient? The application is the balance — energy with tranquility, joy with equanimity. The factors are the path's chemistry.", questions: ["Which awakening factor is strongest in my practice?", "Which is deficient — and what is its antidote?", "Can I feel the difference between balance and intensity?"], references: ["Samyutta Nikaya 46.53", "Bojjhanga Samyutta (SN 46)", "Visuddhimagga"], excerpt: "Mindfulness, investigation, energy, joy, tranquility, concentration, equanimity — the seven factors.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "bojjhangas", "seven_factors", "awakening", "mindfulness", "investigation", "energy", "joy", "tranquility", "concentration", "equanimity"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Noble Eightfold Path — Complete", tradition: "Buddhism", source: "SN 45.8; Dhammacakkappavattana Sutta", explanation: "The path's eight factors: right view, right intention, right speech, right action, right livelihood, right effort, right mindfulness, right concentration. Grouped as wisdom (view, intention), ethics (speech, action, livelihood), and meditation (effort, mindfulness, concentration). The teaching's precision: the path is not sequential but simultaneous — a path, not a ladder.", application: "Use the eightfold path as the library's life audit: which factor is strongest, which weakest? The application is the simultaneity — all eight trained together, each supporting the others. The path is walked, not climbed.", questions: ["Which of the eight factors is strongest in my life?", "Which is weakest — and what is its cost?", "What is one act of right speech, right effort, or right mindfulness available today?"], references: ["Samyutta Nikaya 45.8", "Dhammacakkappavattana Sutta (SN 56.11)", "The Middle Length Discourses"], excerpt: "Right view, intention, speech, action, livelihood, effort, mindfulness, concentration.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["raja", "karma"], domains: ["learning", "growth", "ethics"], tags: ["buddhism", "eightfold_path", "wisdom", "ethics", "meditation", "simultaneous", "audit"], difficulty: "beginner", minutes: 8 },
  { concept: "The Three Trainings — Sila, Samadhi, Panna", tradition: "Buddhism", source: "DN 33; Visuddhimagga", explanation: "The Buddha's path in three lines: virtue (sila), concentration (samadhi), wisdom (panna). The teaching's precision: the three are interdependent — virtue supports concentration, concentration supports wisdom, wisdom perfects virtue. The path is a cycle, not a sequence.", application: "Use the three trainings as the library's architecture: every practice serves one of the three. The application is the cycle's integrity — ethics without concentration is brittle; concentration without wisdom is blind; wisdom without ethics is dangerous.", questions: ["Which training is my practice's home — and which is neglected?", "Where is my virtue brittle, my concentration blind, my wisdom dangerous?", "Can I feel the cycle's interdependence in my own practice?"], references: ["Digha Nikaya 33", "Visuddhimagga", "The Middle Length Discourses"], excerpt: "Virtue, concentration, wisdom — interdependent, cyclic, complete.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["raja", "karma"], domains: ["learning", "ethics", "growth"], tags: ["buddhism", "three_trainings", "sila", "samadhi", "panna", "virtue", "concentration", "wisdom", "cycle"], difficulty: "intermediate", minutes: 7 },
  { concept: "Kamma — Action and Its Fruit", tradition: "Buddhism", source: "AN 6.63; SN 35.145", explanation: "The Buddha's teaching on kamma: intention (cetana) is kamma. The teaching's precision: kamma is not fate but intention — the volitional quality of action. The fruit is not punishment but the intention's natural ripening, in this life or beyond.", application: "Use the intention-teaching as the library's ethics foundation: before any action, ask the intention. The application is not anxiety about results but clarity about the volitional quality — the one thing actually under control.", questions: ["What is the intention beneath my current action?", "Where is my action's volitional quality unclear — and what is its cost?", "Can I distinguish intention (kamma) from result (vipaka)?"], references: ["Anguttara Nikaya 6.63", "Samyutta Nikaya 35.145", "The Middle Length Discourses"], excerpt: "Intention is kamma. The volitional quality is the action's true content.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["karma", "jnana"], domains: ["ethics", "growth"], tags: ["buddhism", "kamma", "intention", "cetana", "fruit", "ethics", "volition"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Four Perceptions — Contemplating the Body", tradition: "Buddhism", source: "MN 10; DN 22", explanation: "The body contemplation's four postures: walking, standing, sitting, lying down — and the instruction to know the posture. The teaching's precision: mindfulness of posture is not gymnastics but the continuous awareness of the body's state, in all its positions.", application: "Practice the four postures as the library's most portable mindfulness: know the posture, in every position. The application is the continuity — the awareness that follows the body through the day's postures.", questions: ["Can I know my posture right now — walking, standing, sitting, lying?", "Where does posture-awareness break in my day?", "What is the difference between knowing the posture and adjusting it?"], references: ["Maha Satipatthana Sutta (MN 10)", "Digha Nikaya 22", "The Middle Length Discourses"], excerpt: "Walking, standing, sitting, lying down — know the posture.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["raja", "hatha"], domains: ["learning", "health"], tags: ["buddhism", "four_postures", "body_contemplation", "walking", "standing", "sitting", "lying", "portable"], difficulty: "beginner", minutes: 5 },
  { concept: "The Repulsiveness of the Body — Asubha", tradition: "Buddhism", source: "MN 10; DN 22; Visuddhimagga", explanation: "The body contemplation's advanced form: asubha — the repulsiveness of the body. The teaching's precision: not disgust but accuracy — the body's composition (hair, skin, flesh, bones) seen without the ornament of attraction. The antidote to sensual desire, the first hindrance.", application: "Use asubha as the library's antidote practice: when sensual desire is the active hindrance, reflect on the body's composition. The application is not self-hatred but accuracy — the ornament removed, the body seen as it is.", questions: ["Where is sensual desire the active hindrance in my life?", "Can I see the body's composition without disgust or denial?", "What is the difference between accuracy and self-hatred?"], references: ["Maha Satipatthana Sutta (MN 10)", "Digha Nikaya 22", "Visuddhimagga 8"], excerpt: "The body's composition — hair, skin, flesh, bones — seen without ornament.", evidence: "traditional", dimensions: ["body", "thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "asubha", "repulsiveness", "body", "composition", "antidote", "sensual_desire"], difficulty: "advanced", minutes: 8 },
  { concept: "The Four Jhanas — Absorption States", tradition: "Buddhism", source: "AN 9.31; Visuddhimagga 3", explanation: "The Buddha's map of concentration: the four jhanas — first (applied thought, sustained thought, joy, happiness, one-pointedness), second (inner tranquility, unification, joy, happiness), third (equanimity, happiness, mindfulness), fourth (pure equanimity, mindfulness, neither pain nor pleasure). The teaching's precision: the jhanas are trained states, not experiences to chase.", application: "Use the four jhanas as the library's concentration horizon: the goal of concentration practice is not bliss but the fourth jhana's pure equanimity — the platform for insight. The application is the training's patience.", questions: ["What is my concentration practice's current horizon?", "Can I distinguish the jhanas' joy from the jhanas' purpose?", "What is the difference between chasing absorption and training for it?"], references: ["Anguttara Nikaya 9.31", "Visuddhimagga 3", "The Middle Length Discourses"], excerpt: "The four jhanas — from applied thought to pure equanimity.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "four_jhanas", "absorption", "concentration", "equanimity", "joy", "platform"], difficulty: "advanced", minutes: 9 },
  { concept: "The Five Spiritual Faculties — Indriya", tradition: "Buddhism", source: "SN 48.10; AN 6.55", explanation: "The five spiritual faculties: faith (saddha), energy (viriya), mindfulness (sati), concentration (samadhi), wisdom (panna). The teaching's precision: the faculties are balanced in pairs — faith with wisdom, energy with concentration — and mindfulness modulates all. The balance, not the intensity, is the training.", application: "Use the five faculties as the library's practice balance audit: is faith ahead of wisdom (credulity) or wisdom ahead of faith (dry intellect)? Is energy ahead of concentration (restlessness) or concentration ahead of energy (sloth)? The application is the balance's restoration.", questions: ["Which faculty is strongest — and which is deficient?", "Where is my faith ahead of wisdom, or wisdom ahead of faith?", "Can I feel the balance — and its loss — in my own practice?"], references: ["Samyutta Nikaya 48.10", "Anguttara Nikaya 6.55", "Visuddhimagga"], excerpt: "Faith, energy, mindfulness, concentration, wisdom — balanced in pairs, modulated by mindfulness.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["buddhism", "five_faculties", "indriya", "faith", "energy", "mindfulness", "concentration", "wisdom", "balance"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Five Powers — Bala", tradition: "Buddhism", source: "SN 48.10; AN 6.55", explanation: "The five powers — the same five faculties when fully developed: faith-power, energy-power, mindfulness-power, concentration-power, wisdom-power. The teaching's precision: the faculty becomes a power when it is unshakable — when the hindrances cannot dislodge it. The progression is the path's measure.", application: "Use the faculty-power distinction as the library's progress measure: not 'do I have mindfulness' but 'is mindfulness unshakable?' The application is the honest audit — the power's presence is known by its resistance to dislodging.", questions: ["Which faculty has become a power — unshakable — in my practice?", "Where is my mindfulness still dislodgable — and by what?", "What is the difference between having a faculty and its being a power?"], references: ["Samyutta Nikaya 48.10", "Anguttara Nikaya 6.55", "Visuddhimagga"], excerpt: "The faculties, fully developed, become powers — unshakable by the hindrances.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["buddhism", "five_powers", "bala", "unshakable", "progress", "measure", "faculties"], difficulty: "advanced", minutes: 8 },
  { concept: "The Four Noble Ones — The Sangha's Hierarchy", tradition: "Buddhism", source: "SN 55.5; AN 11.1", explanation: "The Buddha's classification of the noble ones: stream-enterer (sotapanna), once-returner (sakadagami), non-returner (anagami), and arahant. The teaching's precision: the hierarchy is not of status but of fetters — each stage has its specific abandoned fetters, and the path is the fetters' progressive abandonment.", application: "Use the four noble ones as the library's progress map — not to rank practitioners but to name the fetters. The application is the fetter's identification: which fetter (identity-view, doubt, clinging to rites, sensual desire, ill will, desire for form, desire for formlessness, conceit, restlessness, ignorance) is active in me?", questions: ["Which fetter is active in my current difficulty?", "What is the difference between stage-ranking and fetter-naming?", "Can I name my fetters without shame — as the path's map?"], references: ["Samyutta Nikaya 55.5", "Anguttara Nikaya 11.1", "Visuddhimagga"], excerpt: "Stream-enterer, once-returner, non-returner, arahant — the fetters' progressive abandonment.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "four_noble_ones", "sotapanna", "sakadagami", "anagami", "arahant", "fetters", "progress_map"], difficulty: "advanced", minutes: 9 },
  { concept: "The Fetter Model — Samyojana", tradition: "Buddhism", source: "SN 35.54; DN 33", explanation: "The Buddha's fetter model: ten fetters bind beings to the cycle — identity-view (sakkaya-ditthi), doubt (vicikiccha), clinging to rites and rituals (silabbata-paramasa), sensual desire (kama-raga), ill will (vyapada), desire for form (rupa-raga), desire for the formless (arupa-raga), conceit (mana), restlessness (uddhacca), ignorance (avijja). The first three fall at stream-entry; the next two at non-returning; the last five at arahantship.", application: "Use the ten fetters as the library's most precise diagnostic: name the active fetter. The application is the fetter's specificity — 'I am restless' is vague; 'uddhacca is active' is workable. The map's precision is its mercy.", questions: ["Which of the ten fetters is active in me right now?", "What is the fetter's specific antidote?", "Can I name it precisely — and work with it, rather than with vague discomfort?"], references: ["Samyutta Nikaya 35.54", "Digha Nikaya 33", "Visuddhimagga"], excerpt: "Ten fetters — from identity-view to ignorance. Name the active one.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "fetters", "samyojana", "ten_fetters", "identity_view", "doubt", "conceit", "restlessness", "ignorance", "diagnostic"], difficulty: "advanced", minutes: 10 },
  { concept: "The Buddha's First Sermon — Setting the Wheel in Motion", tradition: "Buddhism", source: "Dhammacakkappavattana Sutta (SN 56.11)", explanation: "The historical teaching: at Sarnath, to the five ascetics, the Buddha set the wheel of dharma in motion — the four noble truths, the middle way, the eightfold path. The sutta's precision: the teaching was not a philosophy lecture but a medical diagnosis — symptom, cause, prognosis, treatment.", application: "Use the first sermon's structure as the library's teaching model: every wisdom entry should diagnose (symptom), identify (cause), promise (prognosis), and prescribe (treatment). The application is the structure's integrity — not the content's novelty.", questions: ["What is my current suffering's symptom, cause, prognosis, and treatment?", "Where is my practice philosophy without prescription?", "Can I hold the teaching as medicine — not as metaphysics?"], references: ["Dhammacakkappavattana Sutta (SN 56.11)", "Samyutta Nikaya 56", "The Middle Length Discourses"], excerpt: "At Sarnath, the wheel was set in motion — diagnosis, cause, prognosis, treatment.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "jnana"], domains: ["learning", "spirituality"], tags: ["buddhism", "first_sermon", "sarnath", "wheel", "four_noble_truths", "medicine", "diagnosis"], difficulty: "beginner", minutes: 7 },
  { concept: "The Parable of the Poisoned Arrow — The Pragmatic Frame", tradition: "Buddhism", source: "Culamalunkyovada Sutta (MN 63)", explanation: "The Buddha's famous parable: a man shot by a poisoned arrow refuses treatment until he knows who shot it, what wood, what feather. He dies before the answers. The teaching: the metaphysical questions — the world's eternity, the soul's existence — are like the arrow's details. The treatment is urgent; the speculation is fatal.", application: "Use the parable as the library's pragmatism test: is this inquiry treating the arrow or cataloguing it? The application is the urgency's restoration — the practice is the treatment; the theory is the wood's species.", questions: ["Where am I cataloguing the arrow instead of treating it?", "What is my practice's urgent treatment — and what is its delay?", "Can I distinguish the speculation that serves the treatment from the speculation that replaces it?"], references: ["Culamalunkyovada Sutta (MN 63)", "The Middle Length Discourses", "Samyutta Nikaya 56"], excerpt: "The man dies before the answers. The treatment is urgent; the speculation is fatal.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "poisoned_arrow", "parable", "pragmatism", "urgency", "speculation", "treatment"], difficulty: "beginner", minutes: 6 },
  { concept: "The Blind Men and the Elephant — The Many Perspectives", tradition: "Buddhism", source: "Tittha Sutta (AN 3.61); Udana 6.4", explanation: "The Buddha's parable: blind men touch an elephant — trunk, ear, tusk, tail — and each declares the elephant is like what they touched. The teaching: the traditions' partial views are like the blind men's — each touching one aspect, each declaring the whole. The parable's precision: it critiques all exclusive claims, including the Buddha's own followers'.", application: "Use the parable as the library's pluralism foundation: every tradition touches the elephant. The application is the humility — my view is a trunk, not the elephant. The library's knowledge graph embodies this: many entries, one reality.", questions: ["Which part of the elephant am I touching — and declaring the whole?", "What is my view's partiality — and what is its cost?", "Can I hold my view as a trunk, not the elephant?"], references: ["Tittha Sutta (AN 3.61)", "Udana 6.4", "The Minor Discourses"], excerpt: "Each blind man touched one part and declared the whole. The elephant is not any part.", evidence: "traditional", dimensions: ["thought", "connection", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "relationships"], tags: ["buddhism", "blind_men", "elephant", "parable", "pluralism", "partiality", "humility"], difficulty: "beginner", minutes: 6 },
  { concept: "The Mustard Seed — The Universality of Loss", tradition: "Buddhism", source: "Kisa Gotami Sutta; SN 57.1", explanation: "The Buddha's story: Kisa Gotami, whose child died, carried the body begging for medicine. The Buddha sent her for a mustard seed from a house where no one had died. House after house — every home had lost someone. The seed was never brought; the lesson was. The teaching: loss is universal; grief is not yours alone.", application: "Use the mustard seed as the library's grief teaching: the universality of loss is not consolation but accuracy. The application is the grief's relocation — from 'my loss' to 'the human condition' — without diminishing the loss.", questions: ["What is my current mustard seed — and what has it taught?", "Where is my grief isolating me — and what would its universality change?", "Can I hold the loss as mine and as universal, simultaneously?"], references: ["Kisa Gotami Sutta", "Samyutta Nikaya 57.1", "The Minor Discourses"], excerpt: "Every house had lost someone. The seed was never brought; the lesson was.", evidence: "traditional", dimensions: ["emotion", "connection", "spirit"], paths: ["bhakti", "raja"], domains: ["growth", "relationships"], tags: ["buddhism", "mustard_seed", "kisa_gotami", "grief", "loss", "universality", "parable"], difficulty: "beginner", minutes: 7 },
  { concept: "The Two Arrows — The Teaching on Suffering's Layers", tradition: "Buddhism", source: "Sallatha Sutta (SN 36.6)", explanation: "The Buddha's two-arrow teaching: struck by the first arrow (pain), the untaught person shoots themselves with the second (the story — 'why me', 'it's unfair'). The teaching's precision: the first arrow is unavoidable; the second is optional. The difference between pain and suffering is the second arrow.", application: "Use the two arrows as the library's most practical pain teaching: when pain arrives, watch for the second arrow's assembly. The application is not the first arrow's avoidance (impossible) but the second's refusal (trainable).", questions: ["Where is the first arrow's pain — and where is my second arrow?", "What story am I shooting into the wound?", "Can I feel the difference between pain (unavoidable) and suffering (optional)?"], references: ["Sallatha Sutta (SN 36.6)", "Samyutta Nikaya 36", "The Middle Length Discourses"], excerpt: "The first arrow is unavoidable; the second is optional. Pain and suffering differ by the second arrow.", evidence: "traditional", dimensions: ["emotion", "thought", "body"], paths: ["raja", "jnana"], domains: ["health", "growth"], tags: ["buddhism", "two_arrows", "pain", "suffering", "story", "second_arrow", "layers"], difficulty: "beginner", minutes: 6 },
  { concept: "The Raft Parable — The Teaching as Vehicle", tradition: "Buddhism", source: "Alagaddupama Sutta (MN 22)", explanation: "The Buddha's raft parable: the teaching is a raft for crossing the flood — not for carrying on the head. Once across, the raft is left. The teaching's precision: the dharma is a vehicle, not a possession. Clinging to the raft is the flood's continuation in a new form.", application: "Use the raft parable as the library's epistemology: every entry — including this one — is a raft. The application is the holding's lightness: use the teaching, do not carry it. The library's knowledge graph is a raft; the crossing is the practice.", questions: ["Which raft am I currently using — and where am I carrying it?", "What is the flood I am crossing?", "Can I hold the teaching lightly — used, not carried?"], references: ["Alagaddupama Sutta (MN 22)", "The Middle Length Discourses", "Dhammapada 1.1-1.5"], excerpt: "The teaching is a raft for crossing — not for carrying on the head.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "spirituality"], tags: ["buddhism", "raft", "parable", "vehicle", "crossing", "lightness", "epistemology"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Simile of the Snake — Wrong View's Danger", tradition: "Buddhism", source: "Alagaddupama Sutta (MN 22)", explanation: "The Buddha's snake simile: a snake seized by the tail turns and bites — as does the dharma seized wrongly. The teaching's precision: the teaching is not a trophy but a tool; wrong grasping is dangerous. The simile's companion: the water-snake simile — the teaching, like a snake, must be grasped by the neck (correctly) or not at all.", application: "Use the snake simile as the library's safety teaching: every entry is a tool with a correct grasp. The application is the grasp's discipline — the entry is used as intended, not clutched as identity. The library's review-status system embodies this: tools are published when their grasp is clear.", questions: ["Where am I clutching a teaching by the tail?", "What is the correct grasp — the neck — of my current practice?", "Can I distinguish using a teaching from clutching it?"], references: ["Alagaddupama Sutta (MN 22)", "The Middle Length Discourses", "Udana 6.4"], excerpt: "The snake seized by the tail turns and bites. Grasp the teaching by the neck — or not at all.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["jnana", "raja"], domains: ["learning", "safety"], tags: ["buddhism", "snake_simile", "wrong_view", "grasp", "danger", "tool", "safety"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Simile of the Ocean — The Taste of the Dharma", tradition: "Buddhism", source: "Udana 5.5; AN 8.19", explanation: "The Buddha's ocean simile: as the great ocean has one taste — the taste of salt — so the dharma has one taste: the taste of liberation. The teaching's precision: the library's many entries (like the ocean's many creatures, depths, currents) share one taste. The variety is the ocean's; the taste is the dharma's.", application: "Use the ocean simile as the library's quality standard: every entry — practice, wisdom, game, program — should taste of liberation. The application is the taste-test: does this entry, used, lead toward the one taste? The library's knowledge graph is the ocean; the taste is the standard.", questions: ["What is the one taste of my current practice?", "Where is the library's variety obscuring its taste?", "Can I taste liberation — not as a concept but as the practice's actual flavor?"], references: ["Udana 5.5", "Anguttara Nikaya 8.19", "The Minor Discourses"], excerpt: "The ocean has one taste — salt. The dharma has one taste — liberation.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja", "jnana"], domains: ["spirituality", "learning"], tags: ["buddhism", "ocean_simile", "one_taste", "salt", "liberation", "quality_standard"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Simile of the Cloth — The Mind's Staining", tradition: "Buddhism", source: "AN 1.49-1.50; Anguttara Nikaya", explanation: "The Buddha's cloth simile: a white cloth, dipped in dye, takes the dye's color. The mind, stained by defilements, takes their color. The teaching's precision: the mind's original is white — not blank but bright. The defilements are dyes, not the cloth's nature.", application: "Use the cloth simile as the library's optimism foundation: the mind's brightness is original, the staining is acquired. The application is the dye's selection — what is my mind being dipped in today? The input curation is the practice.", questions: ["What dye is my mind being dipped in today?", "Where is the original brightness — and how do I know it?", "Can I distinguish the cloth (bright) from the dye (staining)?"], references: ["Anguttara Nikaya 1.49-1.50", "The Numerical Discourses", "Dhammapada 1.1-1.5"], excerpt: "The white cloth takes the dye's color. The mind's original is bright; the staining is acquired.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["buddhism", "cloth_simile", "staining", "dye", "brightness", "original", "optimism"], difficulty: "beginner", minutes: 6 },
  { concept: "The Simile of the City — The Sense Doors", tradition: "Buddhism", source: "MN 125; AN 4.41", explanation: "The Buddha's city simile: the six sense doors are the city's six gates; the guard at the gate is mindfulness; the city's wealth is the practice's fruit. The teaching's precision: the senses are not enemies but gates — the practice is not walling them but guarding them.", application: "Use the city simile as the library's attention architecture: the six gates (five senses plus mind) are guarded by mindfulness, not walled by suppression. The application is the guard's training — the gate's watchfulness, not the gate's closure.", questions: ["Which gate is unguarded in my life?", "What is entering through it — and what is its effect?", "Can I guard the gate without walling it — watchfulness without suppression?"], references: ["Maha Satipatthana Sutta (MN 10)", "Anguttara Nikaya 4.41", "The Middle Length Discourses"], excerpt: "The six gates, the guard of mindfulness, the city's wealth. Guard, do not wall.", evidence: "traditional", dimensions: ["thought", "body", "action"], paths: ["raja"], domains: ["learning", "growth"], tags: ["buddhism", "city_simile", "sense_doors", "gates", "mindfulness", "guard", "watchfulness"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Simile of the Fetter — The Bondage's Mechanism", tradition: "Buddhism", source: "SN 35.54; Samyutta Nikaya", explanation: "The Buddha's fetter simile: the bond is not the object but the attachment to it. A man bound by a rope is not bound by the rope's wood but by the knot. The teaching's precision: the world does not bind; the grasping binds. The rope is the world; the knot is the craving.", application: "Use the fetter simile as the library's liberation mechanics: the practice is not the world's removal but the knot's untying. The application is the knot's location — where is the grasping's knot today? The untying is the practice; the rope's presence is not the problem.", questions: ["Where is the knot today — and what rope is it tied to?", "What is the difference between the rope (world) and the knot (craving)?", "Can I untie one knot today — not by cutting the rope but by loosening the knot?"], references: ["Samyutta Nikaya 35.54", "The Linked Discourses", "Dhammapada 1.1-1.5"], excerpt: "The bond is not the rope but the knot. The world does not bind; the grasping binds.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["buddhism", "fetter_simile", "knot", "rope", "grasping", "bondage", "liberation_mechanics"], difficulty: "intermediate", minutes: 7 },
];

export const WISDOM_ZEN: WisdomArchetype[] = [
  { concept: "Mu — The Gateless Gate", tradition: "Zen", source: "Mumonkan 1; Zhaozhou's Mu", explanation: "The most famous koan: a monk asks Zhaozhou, 'Does a dog have Buddha-nature?' Zhaozhou says 'Mu' — 'no' or 'nothingness'. The koan's precision: mu is not a denial of Buddha-nature but a demolition of the question's framework. The practitioner sits with mu until the questioner dissolves.", application: "Use mu as the library's koan practice: hold one question — not to answer it but to exhaust the answering. The application is the sitting's patience: mu is not a puzzle to solve but a door to walk through, gateless.", questions: ["What is my current mu — the question I am sitting with?", "What is the difference between solving a koan and passing through it?", "Can I hold mu without turning it into a concept?"], references: ["Mumonkan (The Gateless Gate) case 1", "Zhaozhou's recorded sayings", "The Blue Cliff Record"], excerpt: "A monk asked Zhaozhou: 'Does a dog have Buddha-nature?' Zhaozhou said: 'Mu.'", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "mu", "koan", "zhaozhou", "gateless_gate", "buddha_nature", "dog"], difficulty: "advanced", minutes: 9 },
  { concept: "The Sound of One Hand — Hakuin's Koan", tradition: "Zen", source: "Hakuin's koan curriculum", explanation: "Hakuin's famous koan: what is the sound of one hand clapping? The koan's precision: it is not a riddle about acoustics but a demolition of the two-handed assumption — the duality of subject and object, clapper and sound. The practitioner listens for the sound that is not two.", application: "Use the one-hand koan as the library's non-dual training: in every perception, look for the second hand. The application is the duality's collapse — not in theory but in the listening itself.", questions: ["What is the second hand in my current perception?", "Where is the duality of seer and seen — and what happens when it collapses?", "Can I listen for the sound that is not two?"], references: ["Hakuin's koan curriculum", "The Gateless Gate commentary tradition", "Zen classical koans"], excerpt: "What is the sound of one hand clapping? Listen for the sound that is not two.", evidence: "traditional", dimensions: ["thought", "spirit", "body"], paths: ["zen"], domains: ["spirituality", "learning"], tags: ["zen", "one_hand", "sound", "hakuin", "koan", "non_dual", "duality"], difficulty: "advanced", minutes: 9 },
  { concept: "Shoshin — Beginner's Mind", tradition: "Zen", source: "Shunryu Suzuki, Zen Mind, Beginner's Mind", explanation: "Suzuki Roshi's famous formulation: in the beginner's mind there are many possibilities; in the expert's there are few. The teaching's precision: beginner's mind is not ignorance but openness — the expert's knowledge is not wrong but narrowing. The practice is the mind's renewal, not its emptying.", application: "Use shoshin as the library's daily practice: approach one familiar thing today with beginner's mind. The application is the possibility's restoration — the familiar's strangeness, the known's novelty.", questions: ["What is my expert's mind — and what has it narrowed?", "What familiar thing can I approach with beginner's mind today?", "What is the difference between ignorance and openness?"], references: ["Shunryu Suzuki, Zen Mind, Beginner's Mind (1970)", "Zen classical teachings on freshness"], excerpt: "In the beginner's mind there are many possibilities; in the expert's, few.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "raja"], domains: ["learning", "growth"], tags: ["zen", "shoshin", "beginners_mind", "openness", "possibility", "expert", "renewal"], difficulty: "beginner", minutes: 5 },
  { concept: "Mushin — No-Mind", tradition: "Zen", source: "Takuan Soho's Fudochi Shinmyoroku; Zen classics", explanation: "Mushin — the mind without mind, the unminding. Not thoughtlessness but thought-free: the mind moving without stopping, like water flowing without ponding. Takuan's teaching to the swordsman: the mind must not stop anywhere — stopped at the sword, the mind is already defeated.", application: "Use mushin as the library's action teaching: in the next activity, let the mind not stop anywhere — not on the plan, not on the result, not on the self. The application is the flow's restoration: action without the mind's ponding.", questions: ["Where does my mind stop — on the plan, the result, the self?", "What is the difference between no-mind and no-thought?", "Can I act with the mind not stopping anywhere?"], references: ["Takuan Soho, The Unfettered Mind (Fudochi Shinmyoroku)", "Zen classical teachings", "Hagakure (Yamamoto Tsunetomo)"], excerpt: "The mind must not stop anywhere. Stopped at the sword, the mind is already defeated.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["zen", "raja"], domains: ["work", "growth", "learning"], tags: ["zen", "mushin", "no_mind", "unminding", "flow", "takuan", "sword", "action"], difficulty: "advanced", minutes: 8 },
  { concept: "Satori and Kensho — Seeing One's True Nature", tradition: "Zen", source: "Zen classical literature; kensho tradition", explanation: "The Zen tradition's central events: kensho — seeing one's true nature — and satori — the deeper, often gradual realization. The teaching's precision: kensho is not an experience but a recognition — the seeing of what was always there. The tradition distinguishes the glimpse (kensho) from the deepening (satori), and both from the living (the rest of life).", application: "Use the kensho-satori distinction as the library's realism: glimpses are real but not final. The application is the deepening's discipline — the glimpse's integration into the living. The library's practices are the deepening's instruments, not its substitutes.", questions: ["Have I had a glimpse — and what did I do with it?", "What is the difference between the glimpse, the deepening, and the living?", "Can I hold the glimpse without making it a trophy?"], references: ["Zen classical literature", "The Platform Sutra", "Zen masters' recorded sayings"], excerpt: "Kensho — seeing one's true nature. Satori — the deepening. The living — the rest of life.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["zen"], domains: ["spirituality", "learning"], tags: ["zen", "satori", "kensho", "true_nature", "glimpse", "deepening", "recognition"], difficulty: "advanced", minutes: 9 },
  { concept: "Zazen — Just Sitting", tradition: "Zen", source: "Zen classical practice; Dogen's Shobogenzo", explanation: "Zazen — the seated practice of 'just sitting'. Dogen's teaching: zazen is not a means to enlightenment but enlightenment itself, expressed as sitting. The practice's precision: no object, no goal, no attainment — the sitting is the Buddha's sitting, the practice is the realization.", application: "Use zazen as the library's objectless practice: sit, just sit. The application is the goal's release — not a session toward something but a session as something. The library's other practices are ladders; zazen is the ladder's recognition as unnecessary.", questions: ["Can I sit without a goal — even for ten minutes?", "What is the difference between sitting toward something and sitting as something?", "What is my relationship to attainment — and to its release?"], references: ["Dogen, Shobogenzo (Fukanzazengi)", "Zen classical practice manuals", "The Platform Sutra"], excerpt: "Zazen is not a means to enlightenment but enlightenment itself, expressed as sitting.", evidence: "traditional", dimensions: ["spirit", "thought", "body"], paths: ["zen", "raja"], domains: ["spirituality", "learning"], tags: ["zen", "zazen", "just_sitting", "dogen", "shobogenzo", "objectless", "enlightenment"], difficulty: "intermediate", minutes: 8 },
  { concept: "Shikantaza — Nothing But Sitting", tradition: "Zen", source: "Soto Zen tradition; Dogen", explanation: "Shikantaza — 'nothing but sitting' — the Soto school's central practice: zazen without any object, mantra, or koan. The teaching's precision: the practice is not concentration on nothing but awareness as nothing-in-particular. The objectless is not the absence of object but the presence of awareness.", application: "Use shikantaza as the library's advanced objectless entry: sit, aware, objectless. The application is the awareness's recognition — not the object's absence but the awareness's presence. The practice is the library's horizon: awareness aware of awareness.", questions: ["Can I sit aware, objectless — without making 'objectless' an object?", "What is the difference between the absence of object and the presence of awareness?", "What is my relationship to the objectless — and to its difficulty?"], references: ["Dogen, Shobogenzo", "Soto Zen practice tradition", "Keizan's Zazen Yojinki"], excerpt: "Nothing but sitting — awareness as nothing-in-particular.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["zen", "raja"], domains: ["spirituality"], tags: ["zen", "shikantaza", "objectless", "soto", "dogen", "awareness", "nothing_in_particular"], difficulty: "advanced", minutes: 9 },
  { concept: "Kinhin — Walking Zen", tradition: "Zen", source: "Zen monastic practice", explanation: "Kinhin — the Zen practice of slow walking between sitting periods. The teaching's precision: the walking is not a break from the sitting but its continuation — the same attention, different posture. The pace is deliberately slow: the step's phases (lift, move, place) are the practice's object.", application: "Use kinhin as the library's walking foundation: slow walking, attention on the step's phases. The application is the continuity — the walking is not the sitting's interruption but its extension. The library's walking entries inherit this precision.", questions: ["Can I walk slowly enough to feel the step's phases?", "What is the difference between a break and a continuation?", "Where is my walking — and my sitting — interrupted by my own pacing?"], references: ["Zen monastic practice manuals", "The Zen tradition's kinhin instructions", "Dogen's Shobogenzo"], excerpt: "The walking is not a break from the sitting but its continuation.", evidence: "traditional", dimensions: ["body", "thought", "action"], paths: ["zen", "hatha"], domains: ["learning", "health"], tags: ["zen", "kinhin", "walking", "slow", "continuation", "step_phases", "monastic"], difficulty: "beginner", minutes: 6 },
  { concept: "Samu — Work Practice", tradition: "Zen", source: "Zen monastic tradition; Baizhang's rule", explanation: "Samu — the Zen practice of work: cleaning, cooking, gardening, building — as practice, not as break from practice. Baizhang's famous rule: 'A day without work is a day without food.' The teaching's precision: the work is not the practice's support but its form — the practice is not behind the work but in it.", application: "Use samu as the library's karma-yoga entry: the next task is not the practice's interruption but its form. The application is the work's reclassification — not 'before practice' or 'after practice' but 'as practice'. The library's action entries inherit this reclassification.", questions: ["What is my current work — and is it practice's interruption or form?", "What would 'a day without work is a day without food' change about my day?", "Can I reclassify one task today — from interruption to form?"], references: ["Baizhang's monastic rules", "Zen monastic tradition", "The Zen classics on work"], excerpt: "A day without work is a day without food. The work is the practice's form.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["zen", "karma"], domains: ["work", "growth"], tags: ["zen", "samu", "work", "practice", "baizhang", "form", "karma_yoga"], difficulty: "beginner", minutes: 6 },
  { concept: "The Ten Ox-Herding Pictures", tradition: "Zen", source: "Kakuan's Ten Ox-Herding Pictures (12th century)", explanation: "The Zen tradition's most famous progress map: the ox (the self) is sought, found, tamed, mastered, ridden home, forgotten — and finally, the farmer too is gone, and the moon returns to the sky. The pictures' precision: the path has stages, and the stages' order matters — seeking precedes finding, taming precedes mastery, forgetting precedes return.", application: "Use the ten pictures as the library's progress map: where am I — seeking, finding, taming, mastering, riding, forgetting? The application is the stage's honesty: the map's mercy is its order. The seeking stage is not a failure; it is the first picture.", questions: ["Which of the ten pictures is my current stage?", "What is the next picture — and what is its work?", "Can I hold my stage without shame — as the map's first picture, not its failure?"], references: ["Kakuan's Ten Ox-Herding Pictures", "The Gateless Gate commentary tradition", "Zen classical literature"], excerpt: "Seeking, finding, taming, mastering, riding home, forgotten — and the moon returns to the sky.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["zen", "jnana"], domains: ["learning", "spirituality", "growth"], tags: ["zen", "ox_herding", "ten_pictures", "kakuan", "progress_map", "stages", "seeking", "forgetting"], difficulty: "intermediate", minutes: 9 },
  { concept: "The First Gate — Seeking the Ox", tradition: "Zen", source: "Kakuan's Ten Ox-Herding Pictures, picture 1", explanation: "The first picture: the seeker sets out to find the ox — the true self — following its tracks. The teaching's precision: the seeking is not wrong; it is necessary. The tracks are the practices, the teachings, the library's entries. The seeker is not yet the found — but the seeking is the path's beginning, not its embarrassment.", application: "Use the first gate as the library's permission: seeking is the first picture, not the path's failure. The application is the seeking's honesty — the tracks are followed, the ox is not yet seen. The library's entries are the tracks; the seeking is the practice.", questions: ["Am I in the seeking stage — and can I hold it as the first picture, not the failure?", "What tracks am I following — and are they the ox's?", "What is the difference between seeking (the first picture) and seeking-as-avoidance (the seeking that never arrives)?"], references: ["Kakuan's Ten Ox-Herding Pictures, picture 1", "Zen classical literature"], excerpt: "The seeker follows the tracks. Seeking is the first picture — not the path's failure.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "growth"], tags: ["zen", "ox_herding", "seeking", "first_gate", "tracks", "permission", "beginning"], difficulty: "beginner", minutes: 6 },
  { concept: "The Sixth Gate — Riding the Ox Home", tradition: "Zen", source: "Kakuan's Ten Ox-Herding Pictures, picture 6", explanation: "The sixth picture: the ox is tamed, the herder rides it home — the self and the practice are no longer two. The teaching's precision: the riding is not the end but the integration — the practice is no longer a task but the self's manner. The ox (the self) is ridden home (to the ordinary) — not to a distant stable but to the everyday.", application: "Use the sixth gate as the library's integration teaching: the practice's goal is not a special state but the ordinary's transformation. The application is the riding's recognition — the practice is no longer separate from the day; the day is the practice.", questions: ["Where is my practice still a task — and where is it a manner?", "What would 'riding the ox home' look like in my ordinary day?", "Can I distinguish the special state from the ordinary's transformation?"], references: ["Kakuan's Ten Ox-Herding Pictures, picture 6", "Zen classical literature"], excerpt: "The ox is tamed; the herder rides it home. The practice is no longer a task but a manner.", evidence: "traditional", dimensions: ["spirit", "action", "thought"], paths: ["zen", "karma"], domains: ["growth", "work"], tags: ["zen", "ox_herding", "riding_home", "sixth_gate", "integration", "ordinary", "manner"], difficulty: "advanced", minutes: 8 },
  { concept: "The Eighth Gate — Neither the Ox nor the Herder", tradition: "Zen", source: "Kakuan's Ten Ox-Herding Pictures, picture 8", explanation: "The eighth picture: both the ox and the herder are forgotten — the practice and the practitioner dissolved into the ordinary. The teaching's precision: the forgetting is not loss but completion — the tools are set down when the work is done. The farmer is gone; the field remains, worked.", application: "Use the eighth gate as the library's release teaching: the practices are tools, set down when their work is done. The application is the setting-down's honesty — not the abandonment of practice but the completion of its purpose. The library's entries are tools; the tools are not the work.", questions: ["Where am I still carrying tools whose work is done?", "What is the difference between setting down and abandoning?", "Can I complete a practice — and set it down — without loss?"], references: ["Kakuan's Ten Ox-Herding Pictures, picture 8", "Zen classical literature", "The Gateless Gate"], excerpt: "Both the ox and the herder are forgotten. The tools are set down when the work is done.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["zen", "jnana"], domains: ["spirituality", "growth"], tags: ["zen", "ox_herding", "forgetting", "eighth_gate", "release", "tools", "completion"], difficulty: "advanced", minutes: 8 },
  { concept: "The Tenth Gate — Returning to the Marketplace", tradition: "Zen", source: "Kakuan's Ten Ox-Herding Pictures, picture 10", explanation: "The tenth picture: the realized one returns to the marketplace — not to a cave but to the crowd — with open hands, giving to others. The teaching's precision: the path's end is not withdrawal but return — the marketplace, not the mountain. The final picture's famous line: 'Barefooted and naked of breast, I mingle with the people of the world.'", application: "Use the tenth gate as the library's horizon: the practice's completion is not escape but mingling. The application is the return's courage — the marketplace, not the cave. The library's relationship and action entries inherit this horizon.", questions: ["What is my practice's horizon — the cave or the marketplace?", "What would 'barefooted, mingling with the people' look like in my life?", "Can I hold the return as the completion — not the practice's abandonment but its fulfillment?"], references: ["Kakuan's Ten Ox-Herding Pictures, picture 10", "Zen classical literature", "The Platform Sutra"], excerpt: "Barefooted and naked of breast, I mingle with the people of the world.", evidence: "traditional", dimensions: ["spirit", "connection", "action"], paths: ["zen", "karma", "bhakti"], domains: ["spirituality", "relationships", "work"], tags: ["zen", "ox_herding", "marketplace", "tenth_gate", "return", "mingling", "horizon"], difficulty: "advanced", minutes: 9 },
  { concept: "The Gateless Gate — The Barrier of the Patriarchs", tradition: "Zen", source: "Mumonkan's title and preface", explanation: "The Mumonkan's title teaching: the gateless gate — the barrier of the patriarchs. The teaching's precision: the gate is gateless because there is no gate to pass — the barrier is the mind's assumption that there is a gate. The passing is not through a gate but past an assumption.", application: "Use the gateless gate as the library's barrier teaching: every practice's difficulty is not the practice but the assumption that there is something to pass. The application is the assumption's recognition — the gate was never there; the passing was never blocked.", questions: ["What gate am I trying to pass — and who built it?", "What is the assumption that there is a gate?", "Can I recognize the gatelessness — not as ease but as accuracy?"], references: ["Mumonkan (The Gateless Gate), title and preface", "Wumen Huikai's commentary", "Zen classical literature"], excerpt: "The gateless gate — the barrier of the patriarchs. The gate was never there.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "gateless_gate", "mumonkan", "barrier", "patriarchs", "assumption", "passing"], difficulty: "advanced", minutes: 8 },
  { concept: "The Platform Sutra — Huineng's Sudden Teaching", tradition: "Zen", source: "The Platform Sutra of Huineng", explanation: "The Platform Sutra — the only Chinese text granted sutra status — records Huineng's teaching: enlightenment is sudden, not gradual; the mind's original purity is not achieved but recognized. The teaching's precision: the gradual path is not denied but relativized — the sudden recognition is the path's fruit, not its replacement.", application: "Use the Platform Sutra as the library's sudden-gradual integration: practices are gradual; recognition is sudden. The application is the integration's honesty — the gradual practices are not abandoned for the sudden recognition; they are its preparation and its expression.", questions: ["Where is my practice gradual — and where is its recognition sudden?", "Can I hold both — the gradual's discipline and the sudden's recognition?", "What is the relationship between preparation (gradual) and recognition (sudden)?"], references: ["The Platform Sutra of Huineng (Dunhuang version)", "Huineng's recorded teachings", "Shenxiu and Huineng's verse contest"], excerpt: "Enlightenment is sudden; the mind's original purity is recognized, not achieved.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "platform_sutra", "huineng", "sudden", "gradual", "recognition", "original_purity"], difficulty: "advanced", minutes: 9 },
  { concept: "The Verse Contest — Shenxiu and Huineng", tradition: "Zen", source: "The Platform Sutra, chapter 2", explanation: "The famous contest: Shenxiu's verse — 'The body is the bodhi tree; the mind is like a mirror. Continuously wipe it, and let no dust collect' — and Huineng's response — 'Bodhi has no tree; the mirror has no stand. Originally not one thing exists — where can dust alight?' The teaching's precision: both verses are true; the second is deeper. The first is the gradual's truth; the second is the sudden's.", application: "Use the verse contest as the library's gradual-sudden teaching: wipe the mirror (gradual) and recognize no mirror (sudden). The application is the both-holding — the wiping is not wrong; it is the recognition's preparation. The library's practices are the wiping; the library's wisdom is the recognition.", questions: ["Where is my practice the mirror's wiping — and where its recognition?", "Can I hold both verses as true — and the second as deeper?", "What is the relationship between the wiping and the no-mirror?"], references: ["The Platform Sutra of Huineng, chapter 2", "Shenxiu's verse", "Huineng's verse"], excerpt: "Shenxiu: wipe the mirror. Huineng: originally not one thing exists. Both true; the second deeper.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "verse_contest", "shenxiu", "huineng", "mirror", "dust", "gradual", "sudden", "platform_sutra"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Dry Fecal Matter — Linji's Shock", tradition: "Zen", source: "Linji Lu (The Record of Linji)", explanation: "Linji's famous shout-teaching: the master's shout, the blow, the paradoxical answer — not cruelty but the mind's shock-therapy. The teaching's precision: the conceptual mind is not argued with but interrupted. The shout is not an answer but an interruption — the interruption is the answer.", application: "Use Linji's shock as the library's interruption teaching: when the conceptual mind is stuck, interrupt it — not with another concept but with a shout, a question, a silence. The application is the interruption's recognition: the stuck mind is not fixed by more input but by input's cessation.", questions: ["Where is my mind stuck — and what is its more-input habit?", "What is one interruption available today — a shout, a question, a silence?", "Can I distinguish the interruption (the answer) from the interruption's content (nothing)?"], references: ["Linji Lu (The Record of Linji)", "The Linji school's shout and blow tradition", "Zen classical literature"], excerpt: "The shout is not an answer but an interruption. The interruption is the answer.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["zen"], domains: ["learning", "growth"], tags: ["zen", "linji", "shout", "shock", "interruption", "conceptual_mind", "record_of_linji"], difficulty: "advanced", minutes: 8 },
  { concept: "The Dried Tongue — Dogen's Being-Time", tradition: "Zen", source: "Dogen, Shobogenzo (Uji — Being-Time)", explanation: "Dogen's most radical teaching: being-time (uji) — existence is time, time is existence. The teaching's precision: the moment is not a container for events but the events' very being. The dried tongue (a famous Dogen image) — the Buddha's tongue, dried by the truth's speech — is the image of teaching's exhaustion into being.", application: "Use being-time as the library's temporal teaching: the practice is not in time but is time. The application is the moment's reclassification — not a container to fill but the being's form. The library's micro-practices inherit this: the moment is not the practice's setting but its substance.", questions: ["Where am I treating the moment as a container — and what would its reclassification change?", "What is the difference between time as container and time as being?", "Can I feel the practice as being-time — not as an activity in time but as time's form?"], references: ["Dogen, Shobogenzo, chapter 'Uji' (Being-Time)", "Dogen's Eihei Koroku", "Soto Zen literature"], excerpt: "Being is time; time is being. The moment is not the container but the form.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "dogen", "being_time", "uji", "shobogenzo", "moment", "temporal", "radical"], difficulty: "advanced", minutes: 10 },
  { concept: "The One Bright Pearl — Dogen's Unity", tradition: "Zen", source: "Dogen, Shobogenzo (Kobutsu — The One Bright Pearl)", explanation: "Dogen's teaching on the one bright pearl: the whole universe is one bright pearl — not a metaphor but the literal teaching. The pearl is not the self, not the world, not both, not neither — it is the whole, seen without the seer's division. The teaching's precision: the division is the error; the pearl is the correction.", application: "Use the one bright pearl as the library's unity teaching: the whole is not assembled from parts but recognized as one. The application is the division's recognition — where is the seer's division active? The pearl is not sought; the division is seen through.", questions: ["Where is the seer's division active in my experience?", "What is the difference between assembling the whole and recognizing it?", "Can I hold the one bright pearl — not as a metaphor but as the literal teaching?"], references: ["Dogen, Shobogenzo, chapter 'Kobutsu' (The One Bright Pearl)", "Dogen's Eihei Koroku", "Soto Zen literature"], excerpt: "The whole universe is one bright pearl. The division is the error; the pearl is the correction.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "dogen", "one_bright_pearl", "unity", "whole", "division", "shobogenzo", "recognition"], difficulty: "advanced", minutes: 9 },
  { concept: "The Genjo Koan — The Actualized Koan", tradition: "Zen", source: "Dogen, Shobogenzo (Genjo Koan)", explanation: "Dogen's teaching on the genjo koan — the actualized koan: the koan is not a puzzle from the past but the present moment's very fact. The teaching's precision: the actualized koan is not solved but actualized — lived. The self's study is the koan's study; the study is the self's actualization.", application: "Use the genjo koan as the library's present-moment teaching: the koan is not in the book but in the moment. The application is the moment's reclassification — not a problem to solve but a koan to actualize. The library's reflection-question entries inherit this: the question is not answered but lived.", questions: ["What is my actualized koan — the present moment's very fact?", "What is the difference between solving a koan and actualizing it?", "Can I hold the moment as a koan — not a problem but a fact to live?"], references: ["Dogen, Shobogenzo, chapter 'Genjo Koan'", "Dogen's Eihei Koroku", "Soto Zen literature"], excerpt: "The koan is not a puzzle from the past but the present moment's very fact. It is not solved but actualized.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["zen", "jnana"], domains: ["learning", "spirituality", "growth"], tags: ["zen", "dogen", "genjo_koan", "actualized", "present_moment", "shobogenzo", "living"], difficulty: "advanced", minutes: 9 },
  { concept: "The Mind Is Buddha — Mazu's Declaration", tradition: "Zen", source: "Mazu Daoyi's recorded sayings", explanation: "Mazu Daoyi's famous declaration: 'Mind is Buddha.' The teaching's precision: not 'the mind contains Buddha' but 'mind is Buddha' — the ordinary mind, not a special state. Mazu's later correction: 'Not mind, not Buddha' — the declaration's own demolition, the teaching's self-overcoming.", application: "Use Mazu's declaration-and-correction as the library's teaching method: every declaration is a raft, to be demolished by its own correction. The application is the holding's lightness — the declaration is used, not clung; the correction is welcomed, not feared.", questions: ["What is my current 'mind is Buddha' — and what is its correction?", "Can I use a declaration without clinging to it?", "What is the difference between the declaration's use and its clinging?"], references: ["Mazu Daoyi's recorded sayings", "The Hongzhou school", "Zen classical literature"], excerpt: "Mind is Buddha. Not mind, not Buddha. The declaration demolishes itself.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "mazu", "mind_is_buddha", "declaration", "correction", "self_overcoming", "hongzhou"], difficulty: "advanced", minutes: 8 },
  { concept: "The Ordinary Mind — Mazu's Way", tradition: "Zen", source: "Mazu Daoyi's recorded sayings", explanation: "Mazu's most quoted teaching: 'Ordinary mind is the Way.' No seeking, no striving — the ordinary mind, unmodified, is the way. The teaching's precision: the ordinary is not the mediocre but the unmodified — the mind before the seeking's modification. The way is not found by adding but by subtracting.", application: "Use the ordinary-mind teaching as the library's subtraction foundation: the practice is not the mind's improvement but its unmodification. The application is the seeking's release — not the abandonment of practice but the recognition that the practice modifies the modifier.", questions: ["Where is my seeking modifying the ordinary mind?", "What is the difference between the ordinary (unmodified) and the mediocre (unawake)?", "Can I practice without improving — subtracting, not adding?"], references: ["Mazu Daoyi's recorded sayings", "The Hongzhou school", "Zen classical literature"], excerpt: "Ordinary mind is the Way. No seeking, no striving. The ordinary is the unmodified.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["zen", "jnana"], domains: ["spirituality", "growth"], tags: ["zen", "mazu", "ordinary_mind", "the_way", "unmodified", "subtraction", "seeking"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Cypress in the Courtyard — Zhaozhou's Suchness", tradition: "Zen", source: "Zhaozhou's recorded saying; Mumonkan case 40", explanation: "A monk asks Zhaozhou about the ultimate meaning of Zen. Zhaozhou points to the courtyard cypress: 'The cypress in the courtyard.' The teaching's precision: the ultimate meaning is not behind the cypress but is the cypress — suchness, the thing's very thingness. The pointing is not a metaphor but a demonstration.", application: "Use the cypress as the library's suchness teaching: the ultimate is not behind the ordinary but is the ordinary. The application is the pointing's recognition — not the cypress's symbolism but its suchness. The library's sensory entries inherit this: the thing is the teaching.", questions: ["Where am I looking behind the ordinary for the ultimate?", "What is the cypress in my courtyard — the ordinary thing I am overlooking?", "Can I see the thing's suchness — not its symbol but its thingness?"], references: ["Zhaozhou's recorded sayings", "Mumonkan case 40", "The Blue Cliff Record"], excerpt: "The monk asked about the ultimate meaning. Zhaozhou said: 'The cypress in the courtyard.'", evidence: "traditional", dimensions: ["thought", "spirit", "body"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "zhaozhou", "cypress", "suchness", "ordinary", "ultimate", "pointing", "mumonkan"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Flag in the Wind — The Mind-Moving Debate", tradition: "Zen", source: "The Platform Sutra, chapter 1; the flag debate", explanation: "The famous debate: two monks argue whether the flag moves or the wind moves. Huineng passes and says: 'It is not the flag, not the wind — it is the mind that moves.' The teaching's precision: the movement is not in the objects but in the perceiving mind — the debate's both sides are wrong, and the correction is not a third side but the debate's dissolution.", application: "Use the flag debate as the library's perception teaching: when two positions argue, look for the moving mind behind both. The application is the argument's dissolution — not a third position but the perceiving's recognition. The library's wisdom entries inherit this: the debate is the object; the mind is the subject.", questions: ["What is my current flag-and-wind debate — and what is the moving mind behind it?", "Can I dissolve an argument by recognizing its perceiving mind?", "What is the difference between a third position and the debate's dissolution?"], references: ["The Platform Sutra of Huineng, chapter 1", "The flag debate's classical sources", "Zen classical literature"], excerpt: "Not the flag, not the wind — the mind moves. The debate dissolves in the perceiving.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "growth"], tags: ["zen", "flag", "wind", "mind_moves", "huineng", "debate", "dissolution", "perception"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Cucumber Is a Cucumber — Dongshan's Suchness", tradition: "Zen", source: "Dongshan Liangjie's recorded saying", explanation: "Dongshan's teaching: 'The cucumber is a cucumber; the so-called mind is the mind.' The teaching's precision: the ultimate is not a transformation of the ordinary but the ordinary's suchness — the cucumber does not become a cucumber; it is one. The mind does not become the mind; it is one.", application: "Use Dongshan's cucumber as the library's anti-transformation teaching: the practice does not transform the ordinary into the extraordinary but recognizes the ordinary's suchness. The application is the recognition's simplicity — the cucumber is a cucumber; the practice is the practice.", questions: ["Where am I seeking transformation instead of recognition?", "What is my cucumber — the ordinary thing I am trying to make extraordinary?", "Can I hold the suchness — the cucumber is a cucumber — without boredom?"], references: ["Dongshan Liangjie's recorded sayings", "The Caodong school's literature", "Zen classical literature"], excerpt: "The cucumber is a cucumber; the so-called mind is the mind. Suchness, not transformation.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["spirituality", "learning"], tags: ["zen", "dongshan", "cucumber", "suchness", "ordinary", "recognition", "anti_transformation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Oak Tree in the Garden — Dongshan's Non-Attachment", tradition: "Zen", source: "Dongshan Liangjie's recorded saying", explanation: "Dongshan's famous answer to 'What is the ultimate meaning?' — 'The oak tree in the garden.' The teaching's precision: the ultimate is not a statement but a pointing — and the pointing is not a symbol but the thing itself. The oak is not 'like' the ultimate; the oak is the ultimate's suchness, in oak form.", application: "Use the oak tree as the library's pointing teaching: every entry points — not to itself but to the suchness it participates in. The application is the pointing's recognition: the entry is read, the pointing is seen, the suchness is recognized. The library's knowledge graph is the pointing's network.", questions: ["What is my oak tree — the entry that points beyond itself?", "Can I see the pointing — not the entry's content but its suchness?", "What is the difference between reading the entry and seeing the pointing?"], references: ["Dongshan Liangjie's recorded sayings", "The Caodong school's literature", "Zen classical literature"], excerpt: "The oak tree in the garden. The pointing is not a symbol but the thing itself.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "dongshan", "oak_tree", "pointing", "suchness", "symbol", "thing_itself"], difficulty: "advanced", minutes: 8 },
  { concept: "The Three Pounds of Flax — Dongshan's Weight", tradition: "Zen", source: "Dongshan Liangjie's recorded saying", explanation: "Dongshan's answer to 'What is the Buddha?' — 'Three pounds of flax.' The teaching's precision: the Buddha is not a concept but a weight — three pounds of flax, no more, no less. The answer's shock is its precision: the ultimate is not above the ordinary but is the ordinary, weighed.", application: "Use the three pounds of flax as the library's precision teaching: the practice's answers are not concepts but weights — measurable, ordinary, exact. The application is the precision's restoration: not 'the Buddha is everywhere' (vague) but 'three pounds of flax' (exact).", questions: ["Where is my practice vague instead of exact?", "What is my three pounds of flax — the ordinary weight I am overlooking?", "Can I hold the ultimate as a weight — not a concept but a measure?"], references: ["Dongshan Liangjie's recorded sayings", "The Caodong school's literature", "Zen classical literature"], excerpt: "What is the Buddha? Three pounds of flax. The ultimate is a weight, not a concept.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "dongshan", "three_pounds", "flax", "weight", "precision", "buddha"], difficulty: "advanced", minutes: 8 },
  { concept: "The Moon in the Water — The Reflection's Teaching", tradition: "Zen", source: "Zen classical literature; the moon-in-water image", explanation: "The Zen tradition's image: the moon in the water — the reflection is not the moon, yet the moon is not apart from the reflection. The teaching's precision: the relationship is neither identity nor difference — the reflection is the moon's suchness in water, the water's suchness as reflecting. The image is the library's knowledge graph's metaphor: entries reflect the teaching; the teaching is not apart from the entries.", application: "Use the moon-in-water as the library's reflection teaching: every entry is a reflection — not the teaching itself, yet not apart from it. The application is the reflection's recognition: the entry is used, the reflection is seen, the moon is recognized. The library's graph is the water; the entries are the moon's reflections.", questions: ["Where am I mistaking the reflection for the moon — or the moon for the reflection?", "What is the difference between identity and difference in the reflection's case?", "Can I hold the entry as reflection — used, seen, recognized?"], references: ["Zen classical literature", "The moon-in-water image's sources", "The Jingde Chuandeng Lu"], excerpt: "The moon in the water — neither the moon nor apart from it. The reflection is the suchness.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "moon", "water", "reflection", "suchness", "identity", "difference", "graph"], difficulty: "advanced", minutes: 8 },
  { concept: "The Finger Pointing at the Moon — The Pointer's Teaching", tradition: "Zen", source: "The Platform Sutra; Zen classical literature", explanation: "The Zen tradition's most quoted image: the finger pointing at the moon — the teaching is the finger, not the moon. The teaching's precision: the finger is not wrong (it points truly) but it is not the moon (it is not the teaching's fruit). The error is not using the finger but mistaking it for the moon.", application: "Use the finger-moon image as the library's epistemology: every entry is a finger. The application is the finger's use — look where it points, not at it. The library's entries are fingers; the moon is the practice's fruit. The knowledge graph is the hand; the pointing is the practice.", questions: ["Where am I looking at the finger instead of where it points?", "What is my current moon — the fruit the entries point toward?", "Can I use the entry as a finger — looked past, not at?"], references: ["The Platform Sutra of Huineng", "Zen classical literature", "The Sutra of the Teaching of the Buddha"], excerpt: "The teaching is the finger, not the moon. Look where it points, not at it.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["zen", "jnana"], domains: ["learning", "spirituality"], tags: ["zen", "finger", "moon", "pointing", "epistemology", "use", "fruit"], difficulty: "beginner", minutes: 6 },
  { concept: "The Golden Needle — The Skillful Means", tradition: "Zen", source: "Zen classical literature; the golden needle image", explanation: "The Zen tradition's image of skillful means (upaya): the golden needle — the teaching's instrument is precious not for itself but for the eye it opens. The teaching's precision: the means are golden because they are the path's instruments — not decorative but functional, not ends but means.", application: "Use the golden needle as the library's means-teaching: every entry is an instrument — precious for its function, not its content. The application is the instrument's use: the entry is practiced, not collected. The library's progress system embodies this: completion is the instrument's use, not its accumulation.", questions: ["Where am I collecting instruments instead of using them?", "What is my current golden needle — and what eye is it opening?", "Can I hold the entry as means — functional, not decorative?"], references: ["Zen classical literature", "The upaya tradition", "The Lotus Sutra's upaya chapter"], excerpt: "The golden needle — precious for the eye it opens, not for itself.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["zen", "jnana"], domains: ["learning", "growth"], tags: ["zen", "golden_needle", "upaya", "skillful_means", "instrument", "function", "use"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Broken Mirror — The Realization's Image", tradition: "Zen", source: "Zen classical literature; the broken mirror image", explanation: "The Zen tradition's image of realization: the broken mirror — the mind's wholeness is not a mirror's smoothness but a mirror's breaking. The teaching's precision: the unbroken mirror reflects one thing; the broken mirror reflects everything — the breaking is not damage but completion. The image is the library's non-dual teaching in image form.", application: "Use the broken mirror as the library's realization teaching: the practice's completion is not the mind's smoothness but its breaking — the one-thing-reflecting becoming the everything-reflecting. The application is the breaking's acceptance: not the mirror's destruction but its completion.", questions: ["Where am I seeking smoothness instead of breaking?", "What is the difference between the unbroken mirror (one thing) and the broken mirror (everything)?", "Can I accept the breaking as completion — not as damage?"], references: ["Zen classical literature", "The broken mirror image's sources", "Zen poetry tradition"], excerpt: "The broken mirror reflects everything. The breaking is not damage but completion.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["zen", "jnana"], domains: ["spirituality", "growth"], tags: ["zen", "broken_mirror", "realization", "breaking", "completion", "reflection", "non_dual"], difficulty: "advanced", minutes: 8 },
  { concept: "The Empty Cup — The Beginner's Readiness", tradition: "Zen", source: "The classic Zen story (Nan-in's cup)", explanation: "The famous story: Nan-in pours tea into a scholar's cup until it overflows. 'Your cup is full,' he says. 'Like this cup, you are full of your own opinions. Empty your cup, then I can show you Zen.' The teaching's precision: the teaching is not added to the full cup but received by the empty one.", application: "Use the empty cup as the library's readiness teaching: every entry is received by the empty cup — not the full one. The application is the emptying's discipline: not the opinions' destruction but their suspension. The library's ingestion pipeline embodies this: review-status is the cup's emptying before publication.", questions: ["Where is my cup full — and what is it full of?", "What is one opinion I can suspend today — not destroy, suspend?", "Can I receive the entry as the empty cup receives the tea?"], references: ["The classic Zen story of Nan-in's cup", "Zen classical literature", "The Zen tradition's beginner stories"], excerpt: "Your cup is full of opinions. Empty your cup, then I can show you Zen.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["zen", "jnana"], domains: ["learning", "growth"], tags: ["zen", "empty_cup", "nan_in", "readiness", "opinions", "suspension", "receiving"], difficulty: "beginner", minutes: 5 },
];
